<template><div v-if="toast.messages.length" class="toast-stack" aria-live="polite"><div v-for="item in toast.messages" :key="item.id" class="toast" :class="`toast-${item.type || 'info'}`"><Icon :name="item.type === 'success' ? 'heroicons:check-circle' : item.type === 'error' ? 'heroicons:x-circle' : 'heroicons:information-circle'" /><span>{{ item.message }}</span></div></div></template><script setup lang="ts">const toast = useToast()</script>
